#pragma once
// Unit packs: the arc rows a stage unit needs, so dev/unit_packs (UnitPacks) can load just those rows into the
// resource cache in any room (the unit's own sResource::create calls then find them). GENERATED by
// Vibed\StageEditor\unit_arcs\scripts\emit_manifest.py from its packs\*.json: don't edit by hand, rebuild the
// pack and re-run the script. Names only; the data is read from the vanilla arcs under nativePC at run time.
#include <cstdint>

namespace unit_packs {

struct PackRow {
    const char* path;      // game path, no extension
    uint32_t    dti;       // the class's DTI hash = the arc row's type
    const char* arc;       // source arc, relative to nativePC
    uint32_t    size;      // decompressed size
    bool        global;    // also in rom\system\game_cmn / dmc4_cmn (already cached in any room)
};

// A test spawn: a unit of `cls` whose resource field at `field` holds one of `resources` (loaded by the pack).
struct PackSpawn {
    const char*        cls;
    uintptr_t          dti;            // the class's MtDTI object
    uintptr_t          new_instance;   // its MyDTI::newInstance (no arguments, eax = the unit or 0)
    int                move_line;
    uint32_t           field;
    uintptr_t          resource_dti;   // MtDTI object of the resource class
    const char* const* resources;
    int                resource_count;
};

struct Pack {
    const char*      name;
    const char*      room;             // the room the rows come from
    const char*      about;
    const PackRow*   rows;             // in load order: a nested list after its members
    int              row_count;
    const PackSpawn* spawn;            // null = no test spawn
};

extern const Pack kPacks[];
extern const int  kPackCount;

} // namespace unit_packs
